// Cross-check: a proof generated by the WASM prover (/tmp/p3wasm_transfer.json) must verify under
// the native (=runtime) verifier. Proves browser-prove -> runtime-verify interoperability.
use qbc_pq_confidential_p3::transfer;

fn unhex(s: &str) -> Vec<u8> { (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i+2],16).unwrap()).collect() }
fn arr32(s: &str) -> [u8;32] { unhex(s).try_into().unwrap() }
fn field(json: &str, key: &str) -> String {
    let k = format!("\"{key}\":");
    let i = json.find(&k).unwrap() + k.len();
    let rest = &json[i..];
    if rest.starts_with('"') { rest[1..].split('"').next().unwrap().to_string() }
    else { rest.split(|c| c==','||c=='}').next().unwrap().trim().to_string() }
}

#[test]
fn wasm_proof_verifies_natively() {
    let json = std::fs::read_to_string("/tmp/p3wasm_transfer.json").expect("run the wasm prover first");
    // parse the two arrays + fee + proof
    let in0 = field(&json, "in_commitments");  // crude: get the array slice
    let _ = in0;
    // simpler: extract all 32-byte hex tokens in order
    let toks: Vec<&str> = json.matches(|_| false).collect(); let _ = toks;
    // pull commitments by locating quoted 64-hex strings
    let hexes: Vec<String> = {
        let mut v = Vec::new();
        let bytes = json.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            if bytes[i]==b'"' {
                let start=i+1;
                let mut j=start; while j<bytes.len() && bytes[j]!=b'"' {j+=1;}
                let tok=&json[start..j];
                if tok.len()==64 && tok.bytes().all(|c| c.is_ascii_hexdigit()) { v.push(tok.to_string()); }
                i=j+1;
            } else { i+=1; }
        }
        v
    };
    assert!(hexes.len()>=4, "expected 4 commitments");
    let in_c = [arr32(&hexes[0]), arr32(&hexes[1])];
    let out_c = [arr32(&hexes[2]), arr32(&hexes[3])];
    let fee: u64 = field(&json, "fee").parse().unwrap();
    let proof = unhex(&field(&json, "proof_hex"));
    assert!(transfer::verify_transfer(&in_c, &out_c, fee, &proof), "WASM-generated proof must verify natively");
    println!("WASM-prove -> native-verify OK (fee={fee}, proof_bytes={})", proof.len());
}
